phase = 'fwd'
def control(obs):
    global T0, phase
    t = obs['t']
    if T0 is None:
        T0 = t
    el = t - T0
    h = obs['hitch_deg']
    if phase == 'fwd':
        if el < 3.0:
            return (0.0, 0.8, 180)
        phase = 'stop'
        T0 = t
    if phase == 'stop':
        if el < 1.0 and obs['motion']['v_mps'] != 0.0:
            return (0.0, 0.0, 180)
        phase = 'swing'
        T0 = t
    if phase == 'swing':
        if h >= 4.0 or el > 6.0:
            phase = 'follow'
        else:
            return (-15.0, -0.5, 180)
    steer = max(-30.0, min(30.0, 3.0 * (h - 1.0)))
    return (steer, -0.6, 180)

